void UWorldCellIndexTranslationRecordDatabase::PreSave(FObjectPreSaveContext saveContext)
{
	Super::PreSave(saveContext);
	if (saveContext.IsCooking() || saveContext.GetTargetPlatform())
	{
		return;
	}

	FString fullPath = FPaths::ConvertRelativePathToFull(saveContext.GetTargetFilename());
	if (!std::filesystem::exists(TCHAR_TO_UTF8(*fullPath)))
	{
		TArray<FReferencerInformation> internalReferencers;
		TArray<FReferencerInformation> externalReferencers;
		RetrieveReferencers(&internalReferencers, &externalReferencers);

		if (internalReferencers.IsEmpty() && externalReferencers.IsEmpty())
		{
			ArgusStaticData::RegisterNewUWorldCellIndexTranslationRecordDatabase(this);
		}
	}

	Super::PreSave(saveContext);
}

void UWorldCellIndexTranslationRecordDatabase::PostEditChangeProperty(FPropertyChangedEvent& propertyChangedEvent)
{
	if (propertyChangedEvent.ChangeType != EPropertyChangeType::ValueSet)
	{
		return;
	}

	const FString propertyName = propertyChangedEvent.GetPropertyName().ToString();
	const FString recordPropertyName = ARGUS_NAMEOF(m_UWorldCellIndexTranslationRecords);
	if (!propertyName.Equals(recordPropertyName))
	{
		return;
	}

	const int32 arrayIndex = propertyChangedEvent.GetArrayIndex(propertyName);
	UWorldCellIndexTranslationRecord* modifiedUWorldCellIndexTranslationRecord = m_UWorldCellIndexTranslationRecords[arrayIndex].LoadSynchronous();
	if (!modifiedUWorldCellIndexTranslationRecord)
	{
		return;
	}

	modifiedUWorldCellIndexTranslationRecord->m_id = arrayIndex;

	if (!GEditor)
	{
		return;
	}

	UEditorAssetSubsystem* editorAssetSubsystem = GEditor->GetEditorSubsystem<UEditorAssetSubsystem>();
	if (!editorAssetSubsystem)
	{
		return;
	}

	editorAssetSubsystem->SaveLoadedAsset(modifiedUWorldCellIndexTranslationRecord, false);
	editorAssetSubsystem->SaveLoadedAsset(this, false);
}

void UWorldCellIndexTranslationRecordDatabase::AddUWorldCellIndexTranslationRecordToDatabase(UWorldCellIndexTranslationRecord* record)
{
	const int32 arrayIndex = m_UWorldCellIndexTranslationRecords.Num();
	m_UWorldCellIndexTranslationRecords.Add(TSoftObjectPtr(record));

	record->m_id = arrayIndex;

	if (!GEditor)
	{
		return;
	}

	UEditorAssetSubsystem* editorAssetSubsystem = GEditor->GetEditorSubsystem<UEditorAssetSubsystem>();
	if (!editorAssetSubsystem)
	{
		return;
	}

	editorAssetSubsystem->SaveLoadedAsset(this, false);
}

void UWorldCellIndexTranslationRecordDatabase::IterateAllUWorldCellIndexTranslationRecords(const TFunctionRef<void(UWorldCellIndexTranslationRecord*)>& function)
{
	const uint32 upperBound = m_UWorldCellIndexTranslationRecords.Num();
	for (uint32 i = 1u; i < upperBound; ++i)
	{
		function(const_cast<UWorldCellIndexTranslationRecord*>(GetRecord(i)));
	}
}
